    32  struct ExtentsParam
    33  {
    34    inline void init (void)
    35    {
    36      path_open = false;
    37      min_x.set_int (0x7FFFFFFF);
    38      min_y.set_int (0x7FFFFFFF);
    39      max_x.set_int (-0x80000000);
    40      max_y.set_int (-0x80000000);
    41    }
    42
    43    inline void start_path (void) { path_open = true; }
    44    inline void end_path (void) { path_open = false; }
    45    inline bool is_path_open (void) const { return path_open; }
    46
    47    inline void update_bounds (const Point &pt)
    48    {
    49      if (pt.x < min_x) min_x = pt.x;
    50      if (pt.x > max_x) max_x = pt.x;
    51      if (pt.y < min_y) min_y = pt.y;
    52      if (pt.y > max_y) max_y = pt.y;
    53    }
    54
    55    bool  path_open;
    56    Number min_x;
    57    Number min_y;
    58    Number max_x;
    59    Number max_y;
    60  };
