    62  struct CFF2PathProcs_Extents : PathProcs<CFF2PathProcs_Extents, CFF2CSInterpEnv, ExtentsParam>
    63  {
    64    static inline void moveto (CFF2CSInterpEnv &env, ExtentsParam& param, const Point &pt)
    65    {
    66      param.end_path ();
    67      env.moveto (pt);
    68    }
    69
    70    static inline void line (CFF2CSInterpEnv &env, ExtentsParam& param, const Point &pt1)
    71    {
    72      if (!param.is_path_open ())
    73      {
    74        param.start_path ();
    75        param.update_bounds (env.get_pt ());
    76      }
    77      env.moveto (pt1);
    78      param.update_bounds (env.get_pt ());
    79    }
    80
    81    static inline void curve (CFF2CSInterpEnv &env, ExtentsParam& param, const Point &pt1, const Point &pt2, const Point &pt3)
    82    {
    83      if (!param.is_path_open ())
    84      {
    85        param.start_path ();
    86        param.update_bounds (env.get_pt ());
    87      }
    88      /* include control points */
    89      param.update_bounds (pt1);
    90      param.update_bounds (pt2);
    91      env.moveto (pt3);
    92      param.update_bounds (env.get_pt ());
    93    }
    94  };
