   317  struct CFF2PrivateDictOpSet : DictOpSet
   318  {
   319    static inline void process_op (OpCode op, CFF2PrivDictInterpEnv& env, CFF2PrivateDictValues& dictval)
   320    {
   321      NumDictVal val;
   322      val.init ();
   323
   324      switch (op) {
   325        case OpCode_StdHW:
   326        case OpCode_StdVW:
   327        case OpCode_BlueScale:
   328        case OpCode_BlueShift:
   329        case OpCode_BlueFuzz:
   330        case OpCode_ExpansionFactor:
   331        case OpCode_LanguageGroup:
   332          val.single_val = env.argStack.pop_num ();
   333          env.clear_args ();
   334          break;
   335        case OpCode_BlueValues:
   336        case OpCode_OtherBlues:
   337        case OpCode_FamilyBlues:
   338        case OpCode_FamilyOtherBlues:
   339        case OpCode_StemSnapH:
   340        case OpCode_StemSnapV:
   341          env.clear_args ();
   342          break;
   343        case OpCode_Subrs:
   344          dictval.subrsOffset = env.argStack.pop_uint ();
   345          env.clear_args ();
   346          break;
   347        case OpCode_vsindexdict:
   348          env.process_vsindex ();
   349          dictval.ivs = env.get_ivs ();
   350          env.clear_args ();
   351          break;
   352        case OpCode_blenddict:
   353          break;
   354
   355        default:
   356          DictOpSet::process_op (op, env);
   357          if (!env.argStack.is_empty ()) return;
   358          break;
   359      }
   360
   361      if (unlikely (env.in_error ())) return;
   362
   363      dictval.add_op (op, env.substr, val);
   364    }
   365  };
