   367  struct CFF2PrivateDictOpSet_Subset : DictOpSet
   368  {
   369    static inline void process_op (OpCode op, CFF2PrivDictInterpEnv& env, CFF2PrivateDictValues_Subset& dictval)
   370    {
   371      switch (op) {
   372        case OpCode_BlueValues:
   373        case OpCode_OtherBlues:
   374        case OpCode_FamilyBlues:
   375        case OpCode_FamilyOtherBlues:
   376        case OpCode_StdHW:
   377        case OpCode_StdVW:
   378        case OpCode_BlueScale:
   379        case OpCode_BlueShift:
   380        case OpCode_BlueFuzz:
   381        case OpCode_StemSnapH:
   382        case OpCode_StemSnapV:
   383        case OpCode_LanguageGroup:
   384        case OpCode_ExpansionFactor:
   385          env.clear_args ();
   386          break;
   387
   388        case OpCode_blenddict:
   389          env.clear_args ();
   390          return;
   391
   392        case OpCode_Subrs:
   393          dictval.subrsOffset = env.argStack.pop_uint ();
   394          env.clear_args ();
   395          break;
   396
   397        default:
   398          SUPER::process_op (op, env);
   399          if (!env.argStack.is_empty ()) return;
   400          break;
   401      }
   402
   403      if (unlikely (env.in_error ())) return;
   404
   405      dictval.add_op (op, env.substr);
   406    }
