   432    template <typename PRIVOPSET, typename PRIVDICTVAL>
   433    struct accelerator_templ_t
   434    {
   435      inline void init (hb_face_t *face)
   436      {
   437        topDict.init ();
   438        fontDicts.init ();
   439        privateDicts.init ();
   440
   441        this->blob = sc.reference_table<cff2> (face);
   442
   443        /* setup for run-time santization */
   444        sc.init (this->blob);
   445        sc.start_processing ();
   446
   447        const OT::cff2 *cff2 = this->blob->template as<OT::cff2> ();
   448
   449        if (cff2 == &Null(OT::cff2))
   450        { fini (); return; }
   451
   452        { /* parse top dict */
   453          ByteStr topDictStr (cff2 + cff2->topDict, cff2->topDictSize);
   454          if (unlikely (!topDictStr.sanitize (&sc))) { fini (); return; }
   455          CFF2TopDict_Interpreter top_interp;
   456          top_interp.env.init (topDictStr);
   457          topDict.init ();
   458          if (unlikely (!top_interp.interpret (topDict))) { fini (); return; }
   459        }
   460
   461        globalSubrs = &StructAtOffset<CFF2Subrs> (cff2, cff2->topDict + cff2->topDictSize);
   462        varStore = &StructAtOffsetOrNull<CFF2VariationStore> (cff2, topDict.vstoreOffset);
   463        charStrings = &StructAtOffsetOrNull<CFF2CharStrings> (cff2, topDict.charStringsOffset);
   464        fdArray = &StructAtOffsetOrNull<CFF2FDArray> (cff2, topDict.FDArrayOffset);
   465        fdSelect = &StructAtOffsetOrNull<CFF2FDSelect> (cff2, topDict.FDSelectOffset);
   466
   467        if (((varStore != &Null(CFF2VariationStore)) && unlikely (!varStore->sanitize (&sc))) ||
   468            (charStrings == &Null(CFF2CharStrings)) || unlikely (!charStrings->sanitize (&sc)) ||
   469            (fdArray == &Null(CFF2FDArray)) || unlikely (!fdArray->sanitize (&sc)) ||
   470            (((fdSelect != &Null(CFF2FDSelect)) && unlikely (!fdSelect->sanitize (&sc, fdArray->count)))))
   471        { fini (); return; }
   472
   473        num_glyphs = charStrings->count;
   474        if (num_glyphs != sc.get_num_glyphs ())
   475        { fini (); return; }
   476
   477        fdCount = fdArray->count;
   478        privateDicts.resize (fdCount);
   479
   480        /* parse font dicts and gather private dicts */
   481        for (unsigned int i = 0; i < fdCount; i++)
   482        {
   483          const ByteStr fontDictStr = (*fdArray)[i];
   484          if (unlikely (!fontDictStr.sanitize (&sc))) { fini (); return; }
   485          CFF2FontDictValues  *font;
   486          CFF2FontDict_Interpreter font_interp;
   487          font_interp.env.init (fontDictStr);
   488          font = fontDicts.push ();
   489          font->init ();
   490          if (unlikely (!font_interp.interpret (*font))) { fini (); return; }
   491
   492          const ByteStr privDictStr (StructAtOffsetOrNull<UnsizedByteStr> (cff2, font->privateDictInfo.offset), font->privateDictInfo.size);
   493          if (unlikely (!privDictStr.sanitize (&sc))) { fini (); return; }
   494          DictInterpreter<PRIVOPSET, PRIVDICTVAL, CFF2PrivDictInterpEnv>  priv_interp;
   495          priv_interp.env.init(privDictStr);
   496          privateDicts[i].init ();
   497          if (unlikely (!priv_interp.interpret (privateDicts[i]))) { fini (); return; }
   498
   499          privateDicts[i].localSubrs = &StructAtOffsetOrNull<CFF2Subrs> (privDictStr.str, privateDicts[i].subrsOffset);
   500          if (privateDicts[i].localSubrs != &Null(CFF2Subrs) &&
   501            unlikely (!privateDicts[i].localSubrs->sanitize (&sc)))
   502          { fini (); return; }
   503        }
   504      }
   505
   506      inline void fini (void)
   507      {
   508        sc.end_processing ();
   509        fontDicts.fini ();
   510        privateDicts.fini_deep ();
   511        hb_blob_destroy (blob);
   512        blob = nullptr;
   513      }
   514
   515      inline bool is_valid (void) const { return blob != nullptr; }
   516
   517      protected:
   518      hb_blob_t          *blob;
   519      hb_sanitize_context_t   sc;
   520
   521      public:
   522      CFF2TopDictValues    topDict;
   523      const CFF2Subrs        *globalSubrs;
   524      const CFF2VariationStore  *varStore;
   525      const CFF2CharStrings     *charStrings;
   526      const CFF2FDArray    *fdArray;
   527      const CFF2FDSelect  *fdSelect;
   528      unsigned int              fdCount;
   529
   530      hb_vector_t<CFF2FontDictValues>     fontDicts;
   531      hb_vector_t<PRIVDICTVAL>  privateDicts;
   532
   533      unsigned int            num_glyphs;
   534    };
