   543    typedef accelerator_templ_t<CFF2PrivateDictOpSet_Subset, CFF2PrivateDictValues_Subset> accelerator_subset_t;
   544
   545    inline bool subset (hb_subset_plan_t *plan) const
   546    {
   547      hb_blob_t *cff2_prime = nullptr;
   548
   549      bool success = true;
   550      if (hb_subset_cff2 (plan, &cff2_prime)) {
   551        success = success && plan->add_table (HB_OT_TAG_cff2, cff2_prime);
   552        hb_blob_t *head_blob = hb_sanitize_context_t().reference_table<head> (plan->source);
   553        success = success && head_blob && plan->add_table (HB_OT_TAG_head, head_blob);
   554        hb_blob_destroy (head_blob);
   555      } else {
   556        success = false;
   557      }
   558      hb_blob_destroy (cff2_prime);
   559
   560      return success;
   561    }
   562
   563    public:
   564    FixedVersion<HBUINT8> version;        /* Version of CFF2 table. set to 0x0200u */
   565    OffsetTo<TopDict, HBUINT8, false> topDict;   /* headerSize = Offset to Top DICT. */
   566    HBUINT16       topDictSize;      /* Top DICT size */
   567
   568    public:
   569    DEFINE_SIZE_STATIC (5);
   570  };
